const { useState } = React;

function App() {
  const [following, setFollowing] = useState(false);
  const [page, setPage] = useState("profile");

  const handleFollowClick = () => {
    setFollowing(true);
  };

  const handleMessageClick = () => {
    setPage("chat");
  };

  const handleBackToProfile = () => {
    setPage("profile");
  };

  const avatarSize = 100;

  return (
    <>
      <style>{`
        * {
          box-sizing: border-box;
        }
        body {
          margin: 0;
          font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
          background: #fff;
          color: #222;
        }
        header {
          text-align: center;
          padding: 2rem 1rem 1rem;
        }
        .avatar {
          width: ${avatarSize}px;
          height: ${avatarSize}px;
          border-radius: 50%;
          background-color: #ddd;
          margin: 0 auto 1rem;
          position: relative;
          border: 2px solid #999;
        }
        .avatar svg {
          position: absolute;
          top: 50%;
          left: 50%;
          transform: translate(-50%, -50%);
          stroke: #666;
          stroke-width: 3;
        }
        h1 {
          font-weight: 600;
          font-size: 1.8rem;
          margin: 0 0 0.25rem;
          font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
        }
        .role {
          font-style: italic;
          color: #555;
          margin: 0 0 1.5rem;
          font-size: 1rem;
        }
        .btn-group {
          display: flex;
          justify-content: center;
          gap: 1rem;
          margin-bottom: 1.5rem;
        }
        button {
          font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
          font-size: 1rem;
          padding: 0.5rem 1.5rem;
          border-radius: 9999px;
          border: 1.5px solid #444;
          background: transparent;
          cursor: pointer;
          transition: background-color 0.2s ease, color 0.2s ease;
          min-width: 100px;
          user-select: none;
        }
        button:focus {
          outline: 3px solid #4a90e2;
          outline-offset: 2px;
        }
        button.follow {
          border-color: #444;
          color: #444;
        }
        button.follow.following {
          background-color: #444;
          color: white;
          cursor: default;
        }
        button.message {
          border-color: #444;
          color: #444;
        }
        hr {
          border: none;
          border-top: 1.5px solid #ccc;
          margin: 0 1rem 1.5rem;
        }
        main {
          max-width: 480px;
          margin: 0 auto 3rem;
          padding: 0 1rem;
        }
        h2 {
          font-weight: 600;
          font-size: 1.25rem;
          margin-bottom: 0.75rem;
          font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
        }
        p {
          line-height: 1.5;
          color: #333;
          font-size: 1rem;
          margin-top: 0;
        }
        .chat-container {
          max-width: 480px;
          margin: 2rem auto;
          padding: 1rem;
          border: 1.5px solid #ccc;
          border-radius: 8px;
          font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
        }
        .chat-header {
          font-weight: 600;
          font-size: 1.5rem;
          margin-bottom: 1rem;
          text-align: center;
        }
        .chat-message {
          font-size: 1rem;
          color: #555;
          margin-bottom: 1rem;
          text-align: center;
        }
        .btn-back {
          display: block;
          margin: 0 auto;
          padding: 0.5rem 1.5rem;
          font-size: 1rem;
          border-radius: 9999px;
          border: 1.5px solid #444;
          background: transparent;
          cursor: pointer;
          transition: background-color 0.2s ease, color 0.2s ease;
          user-select: none;
        }
        .btn-back:focus {
          outline: 3px solid #4a90e2;
          outline-offset: 2px;
        }
      `}</style>

      {page === "profile" && (
        <>
          <header>
            <div className="avatar" aria-label="User avatar">
              <svg
                width={avatarSize * 0.6}
                height={avatarSize * 0.6}
                viewBox="0 0 100 100"
                fill="none"
                xmlns="http://www.w3.org/2000/svg"
                aria-hidden="true"
              >
                <line x1="10" y1="10" x2="90" y2="90" stroke="#666" strokeWidth="8" />
                <line x1="90" y1="10" x2="10" y2="90" stroke="#666" strokeWidth="8" />
              </svg>
            </div>
            <h1 tabIndex={-1}>Jane Doe</h1>
            <p className="role">Product designer</p>
            <section aria-labelledby="about-title">
              <h2 id="about-title">About</h2>
              <p>
                Jane is a passionate product designer with over 8 years of experience creating user-centered
                designs that solve real-world problems. She loves crafting intuitive interfaces and
                collaborating with cross-functional teams.
              </p>
            </section>
            <div className="btn-group">
              <button
                className={`follow${following ? " following" : ""}`}
                onClick={handleFollowClick}
                disabled={following}
                aria-pressed={following}
                aria-label={following ? "Following Jane Doe" : "Follow Jane Doe"}
              >
                {following ? "Following" : "Follow"}
              </button>
              <button
                className="message"
                onClick={handleMessageClick}
                aria-label="Message Jane Doe"
              >
                Message
              </button>
            </div>
            <hr />
          </header>
          <main></main>
        </>
      )}

      {page === "chat" && (
        <main className="chat-container" role="main">
          <h1 className="chat-header">Chat with Jane Doe</h1>
          <p className="chat-message">This is the chat page. Start your conversation here.</p>
          <button className="btn-back" onClick={handleBackToProfile} aria-label="Back to profile">
            Back to Profile
          </button>
        </main>
      )}
    </>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);

